Here's a sample Java code that uses the Yahoo Finance API to get the exchange rate and perform the currency conversion:
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import org.json.JSONObject;
public class CurrencyConverter {
  public static void main(String[] args) throws Exception {
    // Enter the amount in yen to convert
    double amount = 5000.00;
    // Enter the currency code you want to convert to (e.g., USD, EUR, etc.)
    String toCurrency = "USD";
    // Get the current exchange rate
    String url = "https://query1.finance.yahoo.com/v7/finance/quote?symbols=JPY" + toCurrency + "=X";
    URL yahoo = new URL(url);
    URLConnection yc = yahoo.openConnection();
    BufferedReader in = new BufferedReader(new InputStreamReader(yc.getInputStream()));
    String inputLine;
    StringBuffer response = new StringBuffer();
    while ((inputLine = in.readLine()) != null) {
      response.append(inputLine);
    }
    in.close();
    // Parse the JSON response
    JSONObject json = new JSONObject(response.toString());
    double exchangeRate = json.getJSONArray("quoteResponse")
        .getJSONObject(0)
        .getDouble("regularMarketPrice");
    // Convert yen to the desired currency
    double convertedAmount = amount / exchangeRate;
    System.out.println(amount + " yen is equal to " + convertedAmount + " " + toCurrency);
  }
}

