import org.apache.commons.math3.linear._
import org.apache.commons.math3.transform._
val wavelet = new FastWaveletTransform(new DaubechiesWavelet(2))
val coefficients = new Array2DRowRealMatrix(inputImage.getHeight, inputImage.getWidth)
for (i <- 0 until inputImage.getHeight) {
  val row = new Array[Double](inputImage.getWidth)
  for (j <- 0 until inputImage.getWidth) {
    row(j) = inputImage.getRGB(j, i) & 0xFF
  }
  coefficients.setRow(i, wavelet.transform(row))
}
```
We can then modify the coefficients that pass the threshold of 20.0.
```scala
for (i <- 0 until coefficients.getRowDimension) {
  for (j <- 0 until coefficients.getColumnDimension) {
    if (Math.abs(coefficients.getEntry(i, j)) < 20.0) {
      coefficients.setEntry(i, j, 0.0)
    }
  }
}
```
Finally, we can apply the inverse wavelet transform to obtain the denoised image.
```scala
val outputImage = new BufferedImage(inputImage.getWidth, inputImage.getHeight, BufferedImage.TYPE_BYTE_GRAY)
for (i <- 0 until outputImage.getHeight) {
  val row = wavelet.inverse(coefficients.getRow(i))
  for (j <- 0 until outputImage.getWidth) {
    outputImage.setRGB(j, i, row(j).toInt << 16 | row(j).toInt << 8 | row(j).toInt)
