To analyze the tone of a given text and classify it as formal or informal using C++, you can use Natural Language Processing (NLP) techniques. One common approach is to use a machine learning algorithm, such as a Support Vector Machine (SVM), to train a model on a dataset of labeled formal and informal text samples. Once the model is trained, it can be used to classify new text samples as either formal or informal.
Here is a sample code that uses the SVM algorithm to train a model on a dataset of formal and informal text samples, and then uses the trained model to classify a new text input as either formal or informal:
```c++
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
#include <iterator>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <cstring>
#include <cstdio>
#include <cctype>
#include <locale>
#include <stdexcept>
#include <svm.h>
using namespace std;
// Function to tokenize a string into words
vector<string> tokenize(string str) {
    istringstream iss(str);
    vector<string> tokens{istream_iterator<string>{iss}, istream_iterator<string>{}};
    return tokens;
}
// Function to extract features from a text sample
void extract_features(string sample, svm_node* features, const vector<string>& vocab) {
    // Tokenize the sample into words
    vector<string> words = tokenize(sample);
    // Initialize the feature vector with zeros
    for (int i = 0; i < vocab.size(); i++) {
        features[i].index = i+1;
        features[i].value = 0;
    }
    // Count the occurrence of each word in the sample
    for (int i = 0; i < words.size(); i++) {
        string word = words[i];
        if (find(vocab.begin(), vocab.end(), word) != vocab.end()) {
            int index = find(vocab.begin(), vocab.end(), word) - vocab.begin();
            features[index].value += 1;
        }
    }
    // Normalize the feature vector
    double norm = 0;
    for (int i = 0; i < vocab.size(); i++) {
        norm += pow(features[i].value, 2);
    }
    norm = sqrt(norm);
    for (int i = 0; i < vocab.size(); i++) {
        features[i].value /= norm;
    }
}
// Function to train a model on a dataset of labeled text samples
svm_model* train_model(const vector<string>& samples, const vector<int>& labels, const vector<string>& vocab) {
    // Initialize the SVM problem
    svm_problem problem;
    problem.l = samples.size();
    problem.y = new double[problem.l];
    problem.x = new svm_node*[problem.l];
    // Extract features from the samples
    for (int i = 0; i < samples.size(); i++) {
        svm_node* features = new svm_node[vocab.size()];
        extract_features(samples[i], features, vocab);
        problem.x[i] = features;
        problem.y[i] = labels[i];
    }
    // Set SVM parameters
    svm_parameter param;
    param.svm_type = C_SVC;
    param.kernel_type = LINEAR;
    param.C = 1.0;
    param.eps = 1e-4;
    param.cache_size = 100;
    param.shrinking = 1;
    param.probability = 0;
    param.nr_weight = 0;
    param.weight_label = NULL;
    param.weight = NULL;
    // Train the SVM model
    svm_model* model = svm_train(&problem, &param);
    // Free memory
    for (int i = 0; i < samples.size(); i++) {
        delete[] problem.x[i];
    }
    delete[] problem.x;
    delete[] problem.y;
    // Return the trained model
    return model;
}
// Function to classify a text sample as either formal or informal
int classify_sample(string sample, svm_model* model, const vector<string>& vocab) {
    // Extract features from the sample
    svm_node* features = new svm_node[vocab.size()];
    extract_features(sample, features, vocab);
    // Classify the sample using the trained model
    double label = svm_predict(model, features);
    // Free memory
    delete[] features;
    // Return the predicted label
    return (int)label;
}
int main() {
    // Load the formal and informal text samples
    vector<string> formal_samples, informal_samples;
    ifstream formal_file("formal.txt");
    ifstream informal_file("informal.txt");
    string line;
    while (getline(formal_file, line)) {
        formal_samples.push_back(line);
    }
    while (getline(informal_file, line)) {
        informal_samples.push_back(line);
    }
    // Combine the samples into a single dataset
    vector<string> samples = formal_samples;
    samples.insert(samples.end(), informal_samples.begin(), informal_samples.end());
    // Create a vector of labels for the samples
    vector<int> labels(samples.size());
    for (int i = 0; i < formal_samples.size(); i++) {
        labels[i] = 1;
    }
    for (int i = formal_samples.size(); i < samples.size(); i++) {
        labels[i] = -1;
    }
    // Create a vocabulary of words from the samples
    vector<string> vocab;
    for (int i = 0; i < samples.size(); i++) {
        vector<string> words = tokenize(samples[i]);
        vocab.insert(vocab.end(), words.begin(), words.end());
    }
    sort(vocab.begin(), vocab.end());
    vocab.erase(unique(vocab.begin(), vocab.end()), vocab.end());
    // Train an SVM model on the dataset
    svm_model* model = train_model(samples, labels, vocab);
    // Classify a new text sample
    string sample = "Hello, how are you doing today?";
    int label = classify_sample(sample, model, vocab);
    if (label == 1) {
        cout << "The text is formal." << endl;
    } else {
        cout << "The text is informal." << endl;
    }
    // Free memory
    svm_free_and_destroy_model(&model);
    svm_destroy_param(&param);
    return 0;
}
```
Note that this is just a sample code, and it may need to be adapted to your specific use case. Also, you will need to provide your own dataset of labeled formal and informal text samples, as well as modify the code to read in the text input that you want to classify.

