function fraction($decimal)
{
    $numerator = 1;
    $denominator = 1;
    while ($decimal != ($numerator / $denominator)) {
        if ($decimal < ($numerator / $denominator)) {
            $denominator++;
        } else {
            $numerator++;
        }
    }
    return $numerator . "/" . $denominator;
}
