public static String decimalToHex(int decimal) {
    if (decimal == 0) {
        return "0";
    }
    String hex = "";
    while (decimal > 0) {
        int remainder = decimal % 16;
        if (remainder < 10) {
            hex = remainder + hex;
        } else {
            hex = (char) (remainder + 55) + hex;
        }
        decimal /= 16;
    }
    return hex;
}
```
