    for (int i = 0; i < hex.length(); i++) {
        char hexChar = hex.charAt(i);
        int hexValue = Character.isDigit(hexChar) ? hexChar - '0' : hexChar - 'A' + 10;
        decimal = 16 * decimal + hexValue;
