            totalAutonomy += employee.autonomy
            totalGrowthOpportunities += employee.growthOpportunities
            employeeCount += 1
        }

        let averageJobSatisfaction = totalJobSatisfaction / Double(employeeCount)
        let averageRecognition = totalRecognition / Double(employeeCount)
        let averageAutonomy = totalAutonomy / Double(employeeCount)
        let averageGrowthOpportunities = totalGrowthOpportunities / Double(employeeCount)

        let results = [
            "Job Satisfaction": averageJobSatisfaction,
            "Recognition": averageRecognition,
            "Autonomy": averageAutonomy,
            "Growth Opportunities": averageGrowthOpportunities
        ]

        let belowAverageEmployees = employeeData.filter { employee in
            employee.jobSatisfaction < averageJobSatisfaction &&
            employee.recognition < averageRecognition &&
            employee.autonomy < averageAutonomy &&
            employee.growthOpportunities < averageGrowthOpportunities
        }

