```scala
class Stack(size: Int) {
  private val arr = new Array[Int](size)
  private var top = -1

  def push(x: Int): Unit = {
    if (isFull) {
      println("Stack is full")
      System.exit(1)
    }

    println(s"Inserting $x")
    arr(top + 1) = x
    top += 1
  }

  def pop(): Int = {
    if (isEmpty) {
      println("Stack is empty")
      System.exit(1)
    }

    val x = arr(top)
    top -= 1
    x
  }

  def peek(): Int = {
    if (isEmpty) {
      println("Stack is empty")
      System.exit(1)
    }

    arr(top)
  }

  def isEmpty: Boolean = top == -1

  def isFull: Boolean = top == size - 1
}
