  // Initialize CoreNLP
  StanfordCoreNLP pipeline;
  pipeline.setOption("annotators", "tokenize,ssplit,pos,lemma,parse,depparse");
  // Analyze sentence
  string sentence = "The ball was kicked by the boy.";
  auto doc = pipeline.annotate(sentence);
  auto& sentences = doc.sentences();
  auto& tokens = sentences[0].tokens();
  auto& dependencies = sentences[0].enhancedPlusPlusDependencies();
