How can I arrange 9 flowers in a 3x3 grid with the following conditions:
- Each row, column, and diagonal has exactly 3 different colors
- No two flowers of the same color are adjacent to each other
- Additionally, for each color used, I need to come up with a unique garden design that incorporates that color as the primary theme. Each garden should showcase at least three different design elements, and no two gardens should share any of the same design elements.
Here's the PHP code I came up with to generate the flower arrangements and garden designs:
<?php
$colors = array("red", "blue", "green");
$designs = array(
    "red" => array("roses", "tulips", "hibiscus"),
    "blue" => array("hydrangeas", "bluebells", "forget-me-nots"),
    "green" => array("succulents", "ferns", "ivy")
);
$valid_arrangements = array();
// Generate all possible flower arrangements
foreach ($colors as $c1) {
    foreach ($colors as $c2) {
        foreach ($colors as $c3) {
            $arrangement = array($c1, $c2, $c3);
            if (count(array_unique($arrangement)) == 3) {
                $valid_arrangements[] = $arrangement;
            }
        }
    }
}
// Filter arrangements to meet criteria
$filtered_arrangements = array();
foreach ($valid_arrangements as $arrangement) {
    // Check rows
    if (count(array_unique(array($arrangement[0], $arrangement[1], $arrangement[2]))) == 3
        && count(array_unique(array($arrangement[3], $arrangement[4], $arrangement[5]))) == 3
        && count(array_unique(array($arrangement[6], $arrangement[7], $arrangement[8]))) == 3) {
        // Check columns
        if (count(array_unique(array($arrangement[0], $arrangement[3], $arrangement[6]))) == 3
            && count(array_unique(array($arrangement[1], $arrangement[4], $arrangement[7]))) == 3
            && count(array_unique(array($arrangement[2], $arrangement[5], $arrangement[8]))) == 3) {
            // Check diagonals
            if (count(array_unique(array($arrangement[0], $arrangement[4], $arrangement[8]))) == 3
                && count(array_unique(array($arrangement[2], $arrangement[4], $arrangement[6]))) == 3) {
                $filtered_arrangements[] = $arrangement;
            }
        }
    }
}
// Print out filtered arrangements and garden designs
foreach ($filtered_arrangements as $arrangement) {
    echo "<div style='background-color: white; padding: 10px; margin-bottom: 20px;'>\n";
    foreach ($arrangement as $color) {
        echo "<div style='display: inline-block; margin: 5px; width: 50px; height: 50px; background-color: $color;'></div>\n";
