    echo "<h3>Garden Design:</h3>\n";
    foreach ($arrangement as $color) {
        echo "<div style='background-color: $color; padding: 10px; margin-bottom: 10px;'>\n";
        echo "<h4>$color Garden</h4>\n";
        echo "<ul>\n";
        foreach ($designs[$color] as $design_element) {
            echo "<li>$design_element</li>\n";
        }
        echo "</ul>\n";
        echo "</div>\n";
    }
    echo "</div>\n";
}
?>

