public static async Task Main()
{
    HttpClient client = new HttpClient();
    // Replace with actual API endpoints for each platform
    string[] endpoints = {"https://platform1.com/api", "https://platform2.com/api", "https://platform3.com/api", "https://platform4.com/api", "https://platform5.com/api"};
