                }
                delta0[j] = sum;
            }
            double[][][] deltaPool2 = reshape(delta0, 12, 4, 4);
            double[][][] deltaConv2 = maxPoolBackward(deltaPool2, conv2);
            double[][][] deltaPool1 = convolveBackward(deltaConv2, filters2, pool1);
            double[][][] deltaConv1 = maxPoolBackward(deltaPool1, conv1);
            // update filters and weights
            filters1 = updateFilters(x, deltaConv1, filters1, 0.01);
            filters2 = updateFilters(pool1, deltaConv2, filters2, 0.01);
            weights = updateWeights(flattened, delta1, weights, 0.01);
