    }
    public int predict(double[][][] x) {
        // feedforward computation
        double[][][] conv1 = convolve(x, filters1);
        double[][][] pool1 = maxPool(conv1);
        double[][][] conv2 = convolve(pool1, filters2);
        double[][][] pool2 = maxPool(conv2);
        double[] flattened = flatten(pool2);
        double[] hidden = new double[100];
        for (int i = 0; i < 100; i++) {
            double sum = 0.0;
            for (int j = 0; j < 192; j++) {
                sum += flattened[j] * weights[j * 100 + i];
            }
            hidden[i] = sigmoid(sum);
        }
        double output = 0.0;
        for (int i = 0; i < 10; i++) {
            output += hidden[i] * weights[19200 + i];
        }
        output += bias;
        return argmax(softmax(output));
