        int s = filters[0].length;
        int t = filters[0][0].length;
        int q = (p - t) / s + 1;
        double[][][] y = new double[k][q][q];
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < q; j++) {
                for (int l = 0; l < q; l++) {
                    double sum = 0.0;
                    for (int u = 0; u < s; u++) {
                        for (int v = 0; v < t; v
